const e="2026-10-12",a="Wiki read through a summarizer; numbers as the page states them, not measured per hour.",t=[{status:"wiki",id:"credits-index",title:"Credits: The Index (Neptune)",yields:["Credits"],level:"Intermediate",summary:"Play The Index on High Risk: you pay 50,000 Credits to enter and win 250,000 per round you win.",steps:["Go to Neptune and open The Index.","Choose High Risk (entry costs 50,000 Credits).","Win rounds: each round won pays 250,000 Credits (the end screen shows 200,000, which is the net).","The point target is 100. Points come from kills: collect the points enemies drop and deposit them at a bank."],requires:[],boosts:[{name:"Credit Booster",effect:"The wiki disagrees with itself: the Credits page says it affects only the first round, the Index page's example doubles every round. Test it in game",applies:!0}],notes:["The net gain per won round is 200,000 Credits, not 250,000.","Losing a round loses what you paid in; the page does not state how likely that is."],source:{label:"Warframe Wiki: Credits (Farming Tips)",url:"https://wiki.warframe.com/w/Credits"},checked:e,confidence:a},{status:"wiki",id:"credits-profit-taker",title:"Credits: Profit-Taker Orb (Orb Vallis)",yields:["Credits"],level:"Veteran",summary:"The Profit-Taker Orb drops a base of 125,000 Credits, and several boosts stack on that drop.",steps:["Fight the Profit-Taker Orb in Orb Vallis.","Bring the boosts below before you start: they apply to this drop."],requires:[],boosts:[{name:"Chroma Effigy (rank 3)",effect:"Can double the drop",applies:!0},{name:"Credit Booster",effect:"Doubles credits gained",applies:!0},{name:"Credit Blessing",effect:"+25% for 3 hours, from an MR30 player in a public Relay",applies:!0},{name:"Prosperous Retriever / Loyal Retriever",effect:"Chance to double Credit pickups (see the mod below)",applies:!0}],mods:[{name:"Prosperous Retriever",effect:"18% chance to double Credit pickups at max rank",polarity:"Naramon",drain:"2 at rank 0, 7 at rank 5",where:"The Business in Fortuna, at Neutral rank, for one each of seven tags: Sunny Pobber, White-Breasted Virmink, Flossy Sawgaw, Spotted Bolarola, Dappled Horrasque, Sentinel Stover, Brindle Kubrodon"}],notes:["The mod is a Beast companion mod. Khora's Venari cannot equip it and it cannot be equipped together with Loyal Retriever or Resourceful Retriever.","It keeps working while the companion is downed.","How many forma your companion needs for this mod depends on its slot polarities: the mod is Naramon and costs up to 7, so check the capacity in the Builds page before you spend forma."],source:{label:"Warframe Wiki: Credits and Prosperous Retriever",url:"https://wiki.warframe.com/w/Prosperous_Retriever"},checked:e,confidence:a},{status:"wiki",id:"credits-arbitrations",title:"Credits: Arbitrations",yields:["Credits","Endo"],level:"Intermediate",summary:"Each completed Arbitration pays 50,000 Credits, doubled to 100,000 by the Daily First Win Bonus.",steps:["Unlock Arbitrations (Eris Junction on Pluto).","Complete one Arbitration: 50,000 Credits.","Make the first one of the day count: the Daily First Win Bonus doubles it."],requires:["Arbitrations unlocked from Eris Junction on Pluto"],boosts:[{name:"Daily First Win Bonus",effect:"Doubles the 50,000 Credits",applies:!0}],notes:["The same page also lists Arbitrations as an Endo source: rotation B 44.5% for 1,200 Endo, rotation C 35% for 1,500 Endo.","See Starter guides > Arbitrations for how the mode works."],source:{label:"Warframe Wiki: Credits and Endo",url:"https://wiki.warframe.com/w/Credits"},checked:e,confidence:a},{status:"wiki",id:"credits-disruption",title:"Credits: Disruption at Laomedeia (Neptune)",yields:["Credits"],level:"Intermediate",summary:"Disruption at Laomedeia pays 30,000 Credits for rotation B and 50,000 for rotation C.",steps:["Go to Laomedeia on Neptune and play Disruption.","Reach rotation B (30,000 Credits) or rotation C (50,000 Credits)."],requires:[],boosts:[{name:"Credit Booster",effect:"Applies",applies:!0},{name:"Daily First Win Bonus",effect:"Does not apply here",applies:!1}],notes:[],source:{label:"Warframe Wiki: Credits (Farming Tips)",url:"https://wiki.warframe.com/w/Credits"},checked:e,confidence:a},{status:"wiki",id:"aya-bounties",title:"Aya: Necralisk and Cetus bounties",yields:["Aya"],level:"Beginner",summary:"The best Aya chances in the part of the table that could be read are bounty final stages: Necralisk 43.48% and Cetus Steel Path 38.78%.",steps:["Cambion Drift (Deimos): talk to Mother in the Necralisk. Level 40-60 final stage: 43.48% in every rotation; level 5-15 final stage: 18.33%.","Plains of Eidolon (Earth): talk to Konzu in Cetus. Steel Path level 100 final stage: 38.78% (rotation B); level 40-60 stage 4: 25.68% (rotation C).","Orb Vallis (Venus): talk to Eudico in Fortuna. Level 40-60 stage 4: 16.67% (rotation A)."],requires:[],boosts:[{name:"Resource and drop chance boosters",effect:"Do not apply to Aya, nor to bounty rewards",applies:!1}],notes:["These are chances per reward roll, not per hour: a long bounty and a short one with the same chance are not equally fast.","Other rows of the same table: Necralisk level 40-60 stage 4 at 22.22% in every rotation, and Steel Path Necralisk level 100 stages 2 and 3 at 28.57% (rotation C). The first part of the table was read in full; the rest only partly, so a better row may still exist.","Aya buys Void Relics from Varzia's Prime Resurgence and ranks up some Syndicates (2 Aya for rank 4, 3 for rank 5)."],source:{label:"Warframe Wiki: Aya/Drops",url:"https://wiki.warframe.com/w/Aya/Drops"},checked:e,confidence:a+" The table was truncated."},{status:"wiki",id:"aya-void-missions",title:"Aya: Void missions",yields:["Aya"],level:"Beginner",summary:"Void missions also drop Aya; the best row read is Interception at Mithra, tier 4, rotation C: 22.11%.",steps:["Interception, Mithra (Void), tier 4: rotation A 9.09%, B 12.5%, C 22.11%.","Mobile Defense, Aten (Void), tier 4: rotation A 12.5%.","Defense, Belenus (Void), tier 3: rotation A 7.78%, B 9.09%, C 12.5%."],requires:[],boosts:[{name:"Resource and drop chance boosters",effect:"Do not apply to Aya",applies:!1}],notes:["Chances are per reward roll. Rotation C only comes after many rounds, so the 22.11% row is not the quickest per hour.","Aya also appears occasionally as a Relic Pack reward."],source:{label:"Warframe Wiki: Aya and Aya/Drops",url:"https://wiki.warframe.com/w/Aya/Drops"},checked:e,confidence:a+" The table was truncated."},{status:"wiki",id:"kuva-flood",title:"Kuva: Kuva Flood and Kuva Siphon",yields:["Kuva"],level:"Intermediate",summary:"Kuva Flood missions (level 80-100) give 1,100-1,400 Kuva per Siphon destroyed; Kuva Siphon missions (level 25-35) give 550-700.",steps:["Finish The War Within quest.","Look for nodes marked with the Kuva symbol on the planets the Kuva Fortress is orbiting.","Siphon missions need Mastery Rank 5. Destroy Kuva Siphons: 550-700 each (Siphon) or 1,100-1,400 each (Flood)."],requires:["The War Within quest","Mastery Rank 5 for Kuva Siphon missions"],boosts:[{name:"Boosters",effect:"None of the listed boosters apply to Kuva",applies:!1}],notes:["Other sources on the same page: Archon Hunt (12% for 12,000 Kuva on the third mission, needs Veilbreaker), Sortie (12% for 6,000 Kuva), Kuva Survival on Taveuni (200).","The page does not rank the methods; Flood gives the most per run."],source:{label:"Warframe Wiki: Kuva",url:"https://wiki.warframe.com/w/Kuva"},checked:e,confidence:a},{status:"wiki",id:"endo-high-yield",title:"Endo: highest average per roll",yields:["Endo"],level:"Veteran",summary:"Of the Endo tables that could be read, Deepmines Steel Path bounties (1,050 average) and Archon Hunt (968 average) pay the most per roll.",steps:["Deepmines Bounty (Nokko), Steel Path, rotation B: 30% for 3,500 Endo (average 1,050). Needs Nightcap's Fortuna/Venus bounties and The New War.","Archon Hunt, rotation A: 12.1% for 8,000 Endo (average 968). Needs Veilbreaker.","Arbitrations, rotation B: 44.5% for 1,200 Endo (average 534)."],requires:["The New War (Deepmines Steel Path)","Veilbreaker (Archon Hunt)"],boosts:[{name:"Resource and drop chance boosters",effect:"The page lists them as not applying",applies:!1}],notes:["Per roll, not per hour. The page's list was truncated, and its farming tips text could not be read."],source:{label:"Warframe Wiki: Endo",url:"https://wiki.warframe.com/w/Endo"},checked:e,confidence:a+" The page was truncated."},{status:"community",id:"credits-index-xoris",title:"Credits: The Index with the Xoris heavy attack",yields:["Credits"],level:"Intermediate",summary:"Players report using the Xoris glaive's heavy attack to kill enemies in groups in The Index, so points drop fast and credits come quickly.",steps:["Get a Xoris: it is a Corpus melee glaive (Mastery Rank 4). The Deadlock Protocol gives the parts; extra blueprints and parts are sold by Cephalon Simaris.","Its heavy attack makes an explosion with an 8 m radius and no damage falloff (wiki), which is what makes group kills possible.","Play The Index on High Risk and bank the points you collect (the wiki advises banking at 15 held, never more than that, because dying drops them all).",'For the exact solo loadout, read the community thread linked below: it is titled "Easy Solo Index Farm (Frame: Rhino, Weapon (Melee): Xoris 0 Forma)".'],requires:["Xoris (The Deadlock Protocol or Cephalon Simaris)","Index access"],boosts:[{name:"Credit Booster",effect:"See The Index method: the wiki is unclear about which rounds it doubles",applies:!0}],notes:["NOT VERIFIED HERE: the forum thread could not be opened from this server and the Steam guide about it was removed, so the Rhino loadout, the 0-forma build and how fast it is are unknown to FarmFrame. Only the Xoris stats and the Index rules above come from the wiki.",`Whether your AI squadmates' deposits count toward your team is not stated in the Index wiki page. It says unused squad slots are filled by Warframe Specters and that they "can be more easily defeated than the player", which can hand points to the opponent.`,"Treat the speed as a claim to test, not a promise."],source:{label:"Warframe Forums: Easy Solo Index Farm (Rhino, Xoris 0 Forma)",url:"https://forums.warframe.com/topic/1278508-easy-solo-index-farm-frame-rino-weapon-melee-xoris-0-forma-new-not-sure-where-to-put-stuff-like-this/"},checked:e,confidence:"Community strategy. Title seen in a search; page not read. Xoris and Index facts from wiki.warframe.com/w/Xoris and /w/The_Index."},{status:"wiki",id:"forma-sources",title:"Forma: where the blueprint comes from",yields:["Forma","Forma Blueprint"],level:"Beginner",summary:"The best listed drop is Orokin Derelict Defense, rotation C: 22.56% for a Forma blueprint, about 4 rotation C rewards on average.",steps:["Orokin Derelict Defense, rotation C: 22.56% (expected about 4 C rotations).","Acrithis shop: 10 Pathos Clamps for one Forma blueprint.","Market: 20 Platinum for one, or 35 Platinum for a three-Forma bundle.","Daily Tribute, Nightwave ranks (three-Forma bundles) and Teshin (Steel Path, weekly rotation, Steel Essence) also give Forma."],requires:[],boosts:[{name:"Resource and drop chance boosters",effect:"Not stated on the page for Forma",applies:!1}],notes:["Relics: Common relics can give 1 Forma blueprint and Uncommon 2; the page's relic list was cut off.","Steel Path Circuit tiers 1, 3 and 4 list 4.43% per A rotation (about 22 rotations on average).","The page's build cost and build time were not readable, so FarmFrame does not state them."],source:{label:"Warframe Wiki: Forma",url:"https://wiki.warframe.com/w/Forma"},checked:e,confidence:a+" The relic list and crafting section were cut off."},{status:"wiki",id:"orokin-cell-bosses",title:"Orokin Cells: bosses and Sentients",yields:["Orokin Cell","Orokin Cells"],level:"Beginner",summary:"Every boss (including the Stalker) and Sentient enemies can drop an Orokin Cell; you can also buy or craft them.",steps:["Defeat bosses or Sentient enemies. The page names Saturn, Ceres and Deimos as locations.","Boosters apply to in-mission pickups, so use a Resource Booster or Drop Chance Booster while you do.","Shortcut: buy a cell for 10 Platinum, or a reusable Foundry blueprint for 100 Platinum (1 hour per cell; 15,000 Credits, 50,000 Alloy Plate, 50,000 Nano Spores, 25,000 Salvage)."],requires:[],boosts:[{name:"Resource Booster, Drop Chance Booster, Drop Chance Blessing, Retriever mods, SP Drop Chance Booster",effect:"Apply to in-mission pickups, not to bounty or end-of-mission rewards",applies:!0}],notes:["The page gives no drop chances and links a separate Orokin Cell farming guide that could not be read.","Quantity is 1-2 per drop according to the text, 1-1x according to the infobox; the page does not resolve it."],source:{label:"Warframe Wiki: Orokin Cell",url:"https://wiki.warframe.com/w/Orokin_Cell"},checked:e,confidence:a},{status:"wiki",id:"steel-essence-routes",title:"Steel Essence: daily and weekly sources",yields:["Steel Essence"],level:"Intermediate",summary:"Steel Path Incursions give 30 a day, The Circuit tier 9 gives 25, The Descendia floor 18 gives 25 a week, and each Acolyte gives 2.",steps:["Turn on Steel Path in Navigation. Incursion Alerts then appear: 6 a day, 5 each (30 total); clearing a planet's nodes gives 25.","Duviri The Circuit, Steel Path tier 9: 25 Steel Essence.","The Descendia, Steel Path floor 18: 25 a week.","Defeat Acolytes in any Steel Path mission: 2 each, guaranteed. Loot them within 1-3 minutes or they despawn.","Open Void Relics in Steel Path fissures: 1 per relic."],requires:["Steel Path enabled"],boosts:[{name:"Resource Booster and Loyal/Resourceful Retriever",effect:"Apply to Acolyte drops",applies:!0},{name:"Drop Chance Booster, Drop Chance Blessing, SP Drop Chance Booster",effect:"Listed as not applicable",applies:!1}],notes:["Buying every non-rotating Teshin offering once costs 408 Steel Essence; every rotating one costs 730 more (1,138 in total)."],source:{label:"Warframe Wiki: Steel Essence",url:"https://wiki.warframe.com/w/Steel_Essence"},checked:e,confidence:a},{status:"wiki",id:"endo-ayatan",title:"Endo: Ayatan Stars sold to Maroo",yields:["Endo","Ayatan Star"],level:"Beginner",summary:"Maroo buys each Cyan Star for 50 Endo and each Amber Star for 100 Endo; Necralisk bounty stages can give a single Amber Star.",steps:["Cyan Stars: Kuakas and other wildlife on the Plains of Eidolon may drop them, and they are a rare find in Storage Containers and lockers.","Amber Stars: some Cambion Drift (Necralisk), Sanctum Anatomica and Zariman bounty stages give one each, with chances between about 20% and 56% per roll.","Sell the stars to Maroo for Endo."],requires:[],boosts:[{name:"Resource and drop chance boosters",effect:"Apply only to in-mission pickups, not bounty rewards",applies:!1}],notes:["Stars must be picked up by hand: Vacuum, Fetch and Scavenger Drones cannot pull them.","The page gives no figure for Sculptures, only that their Endo value rises when slotted."],source:{label:"Warframe Wiki: Ayatan Star",url:"https://wiki.warframe.com/w/Ayatan_Star"},checked:e,confidence:a},{status:"wiki",id:"orokin-cell-crates",title:"Orokin Cells: break every crate with Xaku or Limbo (Tethys)",yields:["Orokin Cell","Orokin Cells"],level:"Veteran",summary:"The wiki's fastest listed Orokin Cell method: cast a wide-range ability in every room of an Assassination to break all containers, then kill the boss.",steps:["Play the Assassination at Tethys (Saturn): General Sargas Ruk is the quicker kill. Magnacidium (Deimos) with Lephantis also works but is notably longer.","Bring Xaku (4th ability, The Vast Untime, base range 25 m: the page's current best option) or Limbo (4th ability, Cataclysm, base range 16 m). Maximize Power Range and Power Efficiency.","Cast it in every room so every container breaks, and check rooms for loose cells on the ground.","Kill the Assassination target to end the run.","Bring a Beast companion with Loyal or Resourceful Retriever."],requires:["Xaku or Limbo"],boosts:[{name:"Resource Drop Chance Booster, Blessing, Steel Path passive",effect:"Do not affect this method",applies:!1},{name:"Retriever mods",effect:"Recommended by the page",applies:!0}],notes:["Sargas Ruk has a high cell chance and Lephantis four moderate ones; the page gives no numbers.","Deimos cell drops are diluted by Neurodes."],source:{label:"Warframe Wiki: Orokin Cell Farming Guide",url:"https://wiki.warframe.com/w/Orokin_Cell_Farming_Guide"},checked:e,confidence:"Wiki guide, read through a summarizer. The page states no rates; the order is its own fastest-to-slowest ranking."},{status:"wiki",id:"orokin-cell-survival",title:"Orokin Cells and Plastids: Nekros and Khora survival (Gabii)",yields:["Orokin Cell","Orokin Cells","Plastids"],level:"Intermediate",summary:"Run a long Survival with Nekros looting corpses and Khora holding enemies in place; the wiki lists it second after the crate farm.",steps:["Play Survival at Gabii (Ceres), a Dark Sector with a passive +35% Resource Drop Chance bonus, or Titan (Saturn), which gives a little less loot but more Affinity. A Void Fissure helps long runs but is not required.","Nekros casts Desecrate (the Despoil augment is recommended).","Khora casts Strangledome with the Pilfering Strangledome augment and the enemies are killed while held (Whipclaw can do it).","Optional: Nova's Molecular Prime speeds enemies up (it does not add loot) and a weapon with at least 50% Slash, such as the Mk1-Braton, slices corpses for more Desecrate loot."],requires:["Nekros","Khora"],boosts:[{name:"Resource Booster, Resource Drop Chance Booster, Blessing, Steel Path passive",effect:"All apply to this method",applies:!0}],notes:["The page gives no drop numbers for either resource."],source:{label:"Warframe Wiki: Orokin Cell Farming Guide",url:"https://wiki.warframe.com/w/Orokin_Cell_Farming_Guide"},checked:e,confidence:"Wiki guide, read through a summarizer; no rates stated."},{status:"wiki",id:"orokin-cell-fissure",title:"Orokin Cells: Exterminate fissures on Saturn or Ceres",yields:["Orokin Cell","Orokin Cells"],level:"Beginner",summary:"The wiki's own estimate: repeating an Exterminate fissure on Saturn or Ceres is likely to give at least one Orokin Cell per run, often in as little as two minutes.",steps:["Pick an Exterminate Void Fissure on Saturn or Ceres.","Repeat it. An explosive weapon with extra blast radius (the page names Akarius Prime with Primed Fulmination) can open more containers.","Optional: leave Distilling Extractors on Saturn, Ceres or Deimos, which occasionally bring back a bundle of cells (collect them through the companion app)."],requires:[],boosts:[{name:"Resource boosters",effect:"Not stated for this method",applies:!1}],notes:["The two-minute figure is the page's estimate, not a measurement."],source:{label:"Warframe Wiki: Orokin Cell Farming Guide",url:"https://wiki.warframe.com/w/Orokin_Cell_Farming_Guide"},checked:e,confidence:"Wiki guide, read through a summarizer; the figure is the page's own estimate."},{status:"wiki",id:"plastids-uranus",title:"Plastids: Nekros and Khora survival at Ophelia (Uranus)",yields:["Plastids"],level:"Intermediate",summary:"The wiki says Uranus has the highest Plastids chance because the planet has no common resource drops.",steps:["Play Survival at Ophelia (Uranus), on a Void Fissure for long runs if you like.","Nekros casts Desecrate; Khora casts Strangledome with Pilfering Strangledome and enemies are killed while held.","Optional: Nova's Molecular Prime for enemy flow, and a high-Slash weapon to slice corpses.","Bring a Beast companion with Loyal or Resourceful Retriever."],requires:["Nekros","Khora"],boosts:[{name:"Resource Booster and Resource Drop Chance Booster",effect:"Multiply each other",applies:!0},{name:"Resource Drop Chance Blessing",effect:"Multiplies the boosters",applies:!0},{name:"Steel Path passive",effect:"+100% Resource Drop Chance",applies:!0}],notes:["It also gives the Condition Overload mod. The guide says Tellurium here comes only from Archwing and Empyrean modes, but the Tellurium page lists Star Chart mission tables: the wiki disagrees with itself, so check the drop table.","The page's mod configs and three passive methods were cut off and are not included."],source:{label:"Warframe Wiki: Plastids Farming Guide",url:"https://wiki.warframe.com/w/Plastids_Farming_Guide"},checked:e,confidence:"Wiki guide, read through a summarizer and cut off; no numeric rates stated."},{status:"wiki",id:"argon-containers",title:"Argon Crystals: break every container in a Void Capture",yields:["Argon Crystal","Argon Crystals"],level:"Veteran",summary:"The wiki's fastest Argon Crystal method: cast Xaku's or Limbo's ability in every room of a Void Capture to break all containers.",steps:["Play Capture at Hepit (Void) for Lith relics or Ukko (Void) for Meso or Neo relics.","Bring Xaku (The Vast Untime, base range 25 m: the page's current best option) or Limbo (Cataclysm, base range 16 m), with Ability Range and Efficiency maximized.","Cast it in every room (line of sight is not needed). Each broken container leaves one or two Argon Crystal icons on the map (two for Argon Pegmatites). Collect them.","Capture the objective and extract once Loot Radar shows no containers left.","Slower alternative: Survival at Ani or Mot (Void) with Nekros and Khora."],requires:["Xaku or Limbo"],boosts:[{name:"Resource Booster and Retriever Beasts",effect:"Apply",applies:!0},{name:"Resource Drop Chance Booster, Blessing, Steel Path passive",effect:"Do not apply to the container farm, because Argon Pegmatite only drops Argon Crystals",applies:!1}],notes:["The page gives no numeric rates or decay-timer rules."],source:{label:"Warframe Wiki: Argon Crystal Farming Guide",url:"https://wiki.warframe.com/w/Argon_Crystal_Farming_Guide"},checked:e,confidence:"Wiki guide, read through a summarizer; the page states no rates."},{status:"wiki",id:"endo-vodyanoi",title:"Endo: Vodyanoi Arena (Sedna)",yields:["Endo"],level:"Veteran",summary:"The wiki's reward table for Vodyanoi lists Endo x250 at 22%; articles claim much higher hourly rates with an optimized premade team.",steps:["Play the Arena at Vodyanoi, Sedna (Grineer Sealab, level 85, Steel Path 185). The page says it needs 15 Judgement Points.","The same reward pool exists at Yam, Sedna, so the two nodes can be compared."],requires:["15 Judgement Points (per the node page)"],boosts:[{name:"Resource and drop chance boosters",effect:"Apply only to in-mission pickups, not to end-of-mission rewards",applies:!1}],notes:["Per the node page: Endo x250 22%, Credit Cache x5,000 75.5%, Forma Blueprint 0.5%.","COMMUNITY CLAIMS, NOT MEASURED: one article says 2,000-4,000 Endo per Steel Path run with a premade team, another says 10,000+ Endo per hour (about 1,000 a minute). Neither says how it was measured, and the single-run table above does not show it.","Neither article's claim could be checked against a source here."],source:{label:"Warframe Wiki: Vodyanoi",url:"https://wiki.warframe.com/w/Vodyanoi"},checked:e,confidence:"Node table from the wiki, read through a summarizer. Hourly rates come from uncited articles (ggwtb.com and thegamer.com) and are not verified."},{status:"wiki",id:"void-traces-reactant",title:"Void Traces: Reactant in endless Void Fissures",yields:["Void Traces","Void Trace"],level:"Beginner",summary:"Collect 10 Reactant in a Void Fissure mission for 6-30 Void Traces at mission end, and no relic is needed.",steps:["Run a Void Fissure mission. The page says endless ones are a good source of Reactant and suggests Defense, where it is easier to find (it calls these tips opinion).","Collect 10 Reactant: the reward is 6-30 Void Traces, given at mission end.","If teammates pick your relic reward you gain 5 each, up to 3 teammates.","Alternatively the Granum Void gives 5, 10 or 15 Traces (normal, extended, nightmare) at 33.33% per roll."],requires:[],boosts:[{name:"Resource Booster",effect:"Doubles the reward (page formula)",applies:!0},{name:"Resource Weekend Booster",effect:"Doubles the reward",applies:!0},{name:"Endless bonus boosters",effect:"Up to 4, each adds 25%",applies:!0},{name:"Loyal or Resourceful Retriever",effect:"Can double on the 10th Reactant",applies:!0}],notes:["The page states a maximum of 495 and a minimum of 96 with all boosters.","The page's infobox says boosters only affect in-mission pickups, yet its formula applies them to the Reactant reward, and it does not reconcile the two.","Storage cap is (Mastery Rank x 50) + 100; the excess is lost."],source:{label:"Warframe Wiki: Void Traces",url:"https://wiki.warframe.com/w/Void_Traces"},checked:e,confidence:a},{status:"wiki",id:"vosfor-sources",title:"Vosfor: every source",yields:["Vosfor"],level:"Intermediate",summary:"Vosfor comes from dissolving Arcanes with Loid (12-98 each), Elite Archimedea, The Icebind, Kaya and syndicate packs; a 200 Vosfor pack is the usual unit.",steps:["Finish Whispers in the Walls. Loid of Cavia then converts Arcanes you do not need into Vosfor: 12 to 98 per Arcane, and the best ones (Arcane Barrier, Energize, Grace) give 98.","The Icebind, rotation A: 16.88% per roll for 200 Vosfor (about 33.76 on average). It needs Angels of the Zariman, Whispers in the Walls and Elite Archimedea, and is on Yuvan Peak (Earth) through Cephalon Melica.","Elite Archimedea: 20 Vosfor for 28 Research Points, or 50 for 37.","Buy a 200 Vosfor pack: Kaya in Hollvania for 6 Pix Chips, or for 30,000 Standing at Rank 5 from Steel Meridian, Arbiters of Hexis, Cephalon Suda, The Perrin Sequence, Red Veil or New Loka."],requires:["Whispers in the Walls"],boosts:[{name:"Boosters",effect:"None listed for Vosfor",applies:!1}],notes:["Vosfor is untradeable and cannot be sold. An Arcane collection pack costs 200 Vosfor plus 50,000 Credits and gives 3 Arcanes.","Enemy drops: none listed."],source:{label:"Warframe Wiki: Vosfor",url:"https://wiki.warframe.com/w/Vosfor"},checked:e,confidence:a},{status:"wiki",id:"gallium-caches",title:"Gallium: Sabotage and Exterminate resource caches",yields:["Gallium"],level:"Beginner",summary:"The best listed rows are Sealab Sabotage caches at Desdemona (Uranus): 15.49% for 3 Gallium, then 15.49% for 2.",steps:["Desdemona (Uranus), Sealab Sabotage resource caches: 15.49% for 3 (average 0.4647 per roll) and 15.49% for 2.","Plato (Lua), Exterminate resource caches: 10.82% for 2 (0.2164 per roll).","Mars: Gradivus (Sabotage), Hellas (Exterminate) and Ara (Capture) are listed as farming locations, and Titania (Uranus) for an Assassination."],requires:[],boosts:[{name:"Resource Booster, Drop Chance Booster, Blessing, Retriever mods, Steel Path drop chance",effect:"All apply to in-mission pickups, not to bounty or end-of-mission rewards",applies:!0}],notes:["The page itself says its farming tips are opinion. The quantity is 2-4 in the intro and 1-2 in the infobox, which it does not reconcile.","The weekly Conclave challenge reward lists 12.5% for 10 Gallium."],source:{label:"Warframe Wiki: Gallium",url:"https://wiki.warframe.com/w/Gallium"},checked:e,confidence:a},{status:"wiki",id:"nitain-extract",title:"Nitain Extract: Nightwave first",yields:["Nitain Extract"],level:"Beginner",summary:"Nightwave sells Nitain Extract: 5 for 15 Cred, unlimited, which beats every drop chance listed.",steps:["Do Nightwave tasks to earn Cred.","Buy the x5 Nitain Extract offering for 15 Cred. The page calls it evergreen, so you can buy it as many times as you like.","Drops are rare by comparison: Ghoul Purge bounty final stage in Cetus (3.57-4.72%, only during the event), Rotation C resource caches (0.67-2%) and two enemies at 0.129%."],requires:["Nightwave"],boosts:[{name:"Boosters",effect:"Apply only to in-mission pickups, not to bounty or end-of-mission rewards",applies:!1}],notes:["The page is inconsistent about which offering sells it (Amir's Shockwave in the text, Nora's Mix Volume 6 in the infobox).","Nitain Extract is untradeable."],source:{label:"Warframe Wiki: Nitain Extract",url:"https://wiki.warframe.com/w/Nitain_Extract"},checked:e,confidence:a},{status:"wiki",id:"tellurium-caches",title:"Tellurium: Desdemona caches and Steel Path Ophelia",yields:["Tellurium"],level:"Intermediate",summary:"The best listed row is Sealab Sabotage caches at Desdemona (Uranus), 15.49% per rotation C roll; the page also points to Ophelia with Steel Path.",steps:["Desdemona (Uranus), Sealab Sabotage resource caches: 15.49% (rotation C).","Plato (Lua), Exterminate resource caches: 10.82%.","Survival at Ophelia (Uranus) is listed as a farming location, and the page says Steel Path is roughly 4x the drop rate there (anecdotal)."],requires:[],boosts:[{name:"Resource Booster, Drop Chance Booster, Blessing, Retriever mods, Steel Path drop chance",effect:"All apply to in-mission pickups",applies:!0}],notes:["The wiki disagrees with itself: the Plastids guide says Tellurium comes only from Archwing and Empyrean modes, while this page lists Star Chart mission tables. Check the drop table in game.","The page says its farming tips are opinion. Tellurium costs 10 Platinum on the market according to its in-game description."],source:{label:"Warframe Wiki: Tellurium",url:"https://wiki.warframe.com/w/Tellurium"},checked:e,confidence:a},{status:"community",id:"credits-index-solo-frames",title:"Credits: solo Index frames players suggest",yields:["Credits"],level:"Intermediate",summary:"A Steam discussion collects what players run for a solo Index: Rhino for the armor, and alternatives such as Equinox, Nidus, Nova or Mesa.",steps:["Rhino (Iron Skin) is the usual choice because most frames drop to two-digit health in the Index (reply by Zukabazuka).","Equinox with Peaceful Provocation and Night Form at a 30 m range (reply by No_Quarter, who says it is not meta, it just works for them).","Nidus with a range build and a Radiation Opticor to rain points (reply by Indal).","Slow Nova and a Tigris Prime shot after her second ability for groups (reply by Nekki).","Mesa, Limbo, Trinity, Navigator Ivara and Wukong were also named."],requires:["Index access"],boosts:[{name:"Credit Booster",effect:"See The Index method",applies:!0}],notes:["NOT VERIFIED: these are forum replies, not measured results. The thread does not mention the Xoris or credits per hour.",`Octavia was suggested only "provided you know what you're doing".`],source:{label:"Steam Community discussion: solo Index farming (Warframe)",url:"https://steamcommunity.com/app/230410/discussions/0/3211505894106253654"},checked:e,confidence:"Community replies read through a summarizer; no measured rates."},{status:"wiki",id:"neurodes-sabotage",title:"Neurodes: Sabotage caches and Vem Tabook",yields:["Neurodes"],level:"Beginner",summary:"The highest per-roll rows on the wiki table are the weekly Conclave reward (10 at 12.5%), Vem Tabook kills (50% per kill) and Hive Sabotage caches at Naeglar (15.49%, 2 per roll).",steps:["Naeglar (Eris), Hive Sabotage, rotation C caches: 15.49% for 2, average 0.31 per roll.","Marduk (Void), Tier 4 Sabotage caches: 25.29% for 1.","Kill Vem Tabook: 50% per kill, the best enemy source listed.","Fortuna bounties (talk to Eudico): 33.33% at stage 1, 16.67% at stage 4, 1 each."],requires:[],boosts:[{name:"Resource Booster, Drop Chance Booster, Retriever mods",effect:"Apply to in-mission pickups only",applies:!0}],notes:["Rates are per roll, not per hour: the page gives no mission times.","The page was cut off before its own Gathering Tips section, so the wiki's recommended spots are not shown here.","The market sells Neurodes at 10 Platinum each."],source:{label:"Warframe Wiki: Neurodes",url:"https://wiki.warframe.com/w/Neurodes"},checked:e,confidence:a},{status:"wiki",id:"detonite-injector-invasions",title:"Detonite Injector: Grineer invasions",yields:["Detonite Injector"],level:"Beginner",summary:"Completing a Grineer invasion that offers it gives 3 at 75.88% (about 2.28 per roll), far above the Fortuna bounty rows.",steps:["Open the World State Window and pick an invasion whose Grineer reward is Detonite Injector.","Complete it on the Grineer side to get 3 at the end.","Alternative: Fortuna bounty (level 30-50) gives 2 at 33.33% on stage 1 and 16.67% on stage 4."],requires:[],boosts:[{name:"Resource Booster",effect:"The page says boosters affect in-mission pickups only, so end-of-mission invasion rewards are likely not boosted",applies:!1},{name:"Drop Chance Booster and Blessing",effect:"Do not apply to this item",applies:!1}],notes:["Invasion nodes change; check what is active before planning a run.","The page was last updated in 2025-02 (Hotfix 38.0.12), so rates may have changed."],source:{label:"Warframe Wiki: Detonite Injector",url:"https://wiki.warframe.com/w/Detonite_Injector"},checked:e,confidence:a},{status:"wiki",id:"pathos-clamps-duviri",title:"Pathos Clamps: Duviri bosses and Undercroft",yields:["Pathos Clamp"],level:"Intermediate",summary:"Pathos Clamps are guaranteed rewards, not drops: 10 per Orowyrm or Isleweaver chest (15 in The Steel Path) and 1 per Undercroft side portal (3 in Steel Path).",steps:["Beat the Orowyrm at the end of a Duviri cycle and open its chest: 10, or 15 on Steel Path.","Beat the Isleweaver (The Fragmented duet fight) for another chest: 10, or 15 on Steel Path.","Complete Undercroft side portals in The Duviri Experience: 1 each, 3 on Steel Path (story-stage portals give none)."],requires:["Duviri access"],boosts:[{name:"Resource Booster",effect:"Does not affect these sources",applies:!1}],notes:["Untradeable. The page says 1210 are needed for every current Drifter melee, all Incarnon Genesis upgrades, Kullervo and Rauta.","Spending: Syam, Azothane and Edun cost 50 each at Teshin's Cave; Acrithis sells Orokin Reactors, Catalysts and Forma Blueprints for 10-25.","The page gives no run times, so the cheapest route is yours to compare."],source:{label:"Warframe Wiki: Pathos Clamp",url:"https://wiki.warframe.com/w/Pathos_Clamp"},checked:e,confidence:a},{status:"wiki",id:"rubedo-phobos-europa",title:"Rubedo: Phobos and Europa",yields:["Rubedo"],level:"Beginner",summary:"The wiki says Rubedo has a higher chance to drop on Phobos and Europa, usually 15 to 25 per drop.",steps:["Play missions on Phobos or Europa and break resource containers and kill enemies there.","Pick up every Rubedo drop: each gives 15 to 25."],requires:[],boosts:[{name:"Resource Booster, Drop Chance Booster, Blessing, Retriever mods, Steel Path drop chance",effect:"Apply to in-mission pickups, not bounty or end-of-mission rewards",applies:!0}],notes:["The page was cut off before its drop tables, so exact chances are NOT shown: check warframe.com/droptables.","Untradeable and not sellable for Credits. The market lists 30 Platinum for 450 Rubedo."],source:{label:"Warframe Wiki: Rubedo",url:"https://wiki.warframe.com/w/Rubedo"},checked:e,confidence:"Page read through a summarizer; drop tables were cut off."},{status:"wiki",id:"vitus-arbitrations",title:"Vitus Essence: Arbitrations and Shield Drones",yields:["Vitus Essence"],level:"Intermediate",summary:"Arbitrations give 1 Vitus Essence guaranteed per completed rotation, plus a reward-table roll of 3 at 7-10%; Arbitration Shield Drones drop 1 at 6% per kill.",steps:["Unlock Arbitrations at Eris Junction on Pluto and pick a node from the alerts tab of the World State Window.","Finish rotations: each gives 1 Vitus guaranteed, and the table adds 3 at 7% (A, B) or 10% (C), about 0.21-0.30 per roll.","Kill Shield Drones fast (6% for 1, about 17 kills per drop) and loot at once: drops despawn after 5 minutes and often in 1-3."],requires:["Arbitrations unlocked"],boosts:[{name:"Resource Booster, Drop Chance Booster, Blessing, Retriever mods, Steel Path drop chance",effect:"Apply to drone drops (in-mission pickups only)",applies:!0},{name:"Loot rerolls (Desecrate, Pilfering Swarm, Prowl...)",effect:"Cannot reroll drone drops",applies:!1}],notes:["Drones are effectively invulnerable to abilities, so use weapons.","The page says 1,125 Vitus buys everything once from the Arbiters of Hexis."],source:{label:"Warframe Wiki: Vitus Essence",url:"https://wiki.warframe.com/w/Vitus_Essence"},checked:e,confidence:a},{status:"wiki",id:"lanthorn-netracell",title:"Entrati Lanthorn: Netracells and Zariman",yields:["Entrati Lanthorn"],level:"Intermediate",summary:"Netracell runs give a guaranteed Entrati Lanthorn (even after the 5 weekly runs); the table also lists Zariman Exterminate and Mobile Defense at 8.89% and Zariman bounties.",steps:["Run Netracells: guaranteed drop, the wiki's most reliable source.","Zariman Exterminate (Halako Perimeter) or Mobile Defense (The Greenway), rotation A: 8.89% for 1.","Zariman bounty level 70-75 (Quinn): 7.94% for 3.","Sanctum Anatomica Alchemy, Mirror Defense or Survival (Deimos), rotation B: 5% for 1; Rogue Bonewidow and Rogue Voidrig can drop one."],requires:[],boosts:[{name:"Resource Booster, Drop Chance Booster, Blessing, Retriever mods, Steel Path drop chance",effect:"Apply to in-mission pickups, not bounty rewards",applies:!0}],notes:["Gruzzlings can leave a pickup worth 3; the page gives no chance.","Rare storage containers in the Zariman also give Lanthorns; Chroma's Elemental Ward, Limbo's Cataclysm or Xaku's The Vast Untime modded for range break them easily.","The best-spot picks on the page are opinion."],source:{label:"Warframe Wiki: Entrati Lanthorn",url:"https://wiki.warframe.com/w/Entrati_Lanthorn"},checked:e,confidence:a},{status:"wiki",id:"fieldron-invasions",title:"Fieldron: Corpus invasions",yields:["Fieldron"],level:"Beginner",summary:"Corpus invasion rewards give 3 Fieldron at 75.88% (about 2.28 per roll), above the Fortuna bounty rows.",steps:["Pick a Corpus invasion that offers Fieldron in the World State Window and finish it on the Corpus side.","Alternative: Fortuna bounty level 30-50 (Eudico), 2 at 33.33% on stage 1 down to 16.67% on stage 4.","Break rare and reinforced Corpus storage containers."],requires:[],boosts:[{name:"Resource Booster and Retriever mods",effect:"Apply to in-mission pickups only",applies:!0},{name:"Drop Chance Booster and Steel Path drop booster",effect:"Do not apply",applies:!1}],notes:["Untradeable. The page lists no enemy drops and no best spot.","Crafting numbers on the page were ambiguous: check them in game."],source:{label:"Warframe Wiki: Fieldron",url:"https://wiki.warframe.com/w/Fieldron"},checked:e,confidence:a},{status:"wiki",id:"mutagen-deimos",title:"Mutagen Samples: Deimos caches",yields:["Mutagen Sample"],level:"Beginner",summary:"Orokin Derelict caches at Formido and Hive caches at Naeglar give 3 Mutagen Samples per roll (14.29% and 15.49%); the wiki prefers Deimos because samples are uncommon there and rare on Eris.",steps:["Formido (Deimos), Sabotage, rotation A caches: 14.29% for 3.","Naeglar (Eris), Hive Sabotage, rotation B caches: 15.49% for 3.","Opinion spots on the page: Hyf (Defense) and Terrorem (Survival) on Deimos, Cambion Drift, or Xini (Interception) on Eris."],requires:[],boosts:[{name:"Resource Booster, Drop Chance Booster, Blessing, Retriever mods, Steel Path drop chance",effect:"Apply to in-mission pickups, not bounty rewards",applies:!0}],notes:["Not sold for Platinum in the Market. Used for Bio Lab research in the Dojo.","The drop table lists no enemy source."],source:{label:"Warframe Wiki: Mutagen Sample",url:"https://wiki.warframe.com/w/Mutagen_Sample"},checked:e,confidence:a},{status:"wiki",id:"nano-spores-sabotage",title:"Nano Spores: Sabotage caches",yields:["Nano Spores"],level:"Beginner",summary:"Sabotage caches give 1000 Nano Spores per roll: Hive at Naeglar (Eris) 16.67%, Orokin Derelict at Formido (Deimos) 14.29%, about 167 and 143 per roll.",steps:["Naeglar (Eris), Hive Sabotage, rotation A caches: 16.67% for 1000.","Formido (Deimos), Orokin Derelict Sabotage, rotation A caches: 14.29% for 1000.","Fortuna bounty level 10-30 (Eudico): 25% for 200 at stage 1.","Opinion spots on the page: Akkad (Eris Defense), Terrorem and Hyf (Deimos), Piscinas (Saturn Survival)."],requires:[],boosts:[{name:"Resource Booster, Drop Chance Booster, Blessing, Retriever mods, Steel Path drop chance",effect:"Apply to in-mission pickups, not bounty rewards",applies:!0}],notes:["The market sells 3,000 Nano Spores for 30 Platinum.","The page was cut off before its Gathering Tips; the farming spots above are the wiki's own opinion list."],source:{label:"Warframe Wiki: Nano Spores",url:"https://wiki.warframe.com/w/Nano_Spores"},checked:e,confidence:a},{status:"wiki",id:"basic-resources",title:"Ferrite, Alloy Plate and Polymer Bundle: where they are found",yields:["Ferrite","Alloy Plate","Polymer Bundle"],level:"Beginner",summary:"All three are common and drop on many planets; the wiki pages name the planets and quantities, and the market sells them for Platinum.",steps:["Ferrite (usually 50-100 per drop): Mercury, Earth, Neptune, the Void, Lua and the Zariman.","Alloy Plate (usually 50-150 per drop): Venus, Phobos, Ceres, Jupiter, Pluto, Sedna and the Zariman.","Polymer Bundle (usually 40-75 per drop): Mercury, Venus and Uranus, with the best chance on Uranus.","Break resource containers and pick up every drop; any mission on those planets works."],requires:[],boosts:[{name:"Resource Booster, Drop Chance Booster, Blessing, Retriever mods, Steel Path drop chance",effect:"Apply to in-mission pickups, not bounty or end-of-mission rewards",applies:!0}],notes:["The pages were cut off before their drop tables, so no chances are claimed: check warframe.com/droptables for the best mission.","Market listings seen: 3,000 Ferrite for 30 Platinum, 300 Polymer Bundles for 30 Platinum; Alloy Plate is also sold for Platinum."],source:{label:"Warframe Wiki: Ferrite",url:"https://wiki.warframe.com/w/Ferrite"},checked:e,confidence:"Pages read through a summarizer; drop tables were cut off."}];export{t as M};
